import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Host Applier as a Plugin","description":"","frontmatter":{"title":"Host Applier as a Plugin","type":"adr","date":"2026-08-29T00:00:00.000Z","status":"accepted","status_note":"Accepted"},"headers":[],"relativePath":"handl/project/adrs/0036-host-applier-as-plugin.md","filePath":"vendored/handl/project/adrs/0036-host-applier-as-plugin.md"}`),a={name:`handl/project/adrs/0036-host-applier-as-plugin.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0036-host-applier-as-a-plugin" tabindex="-1">ADR-0036: Host Applier as a Plugin <a class="header-anchor" href="#adr-0036-host-applier-as-a-plugin" aria-label="Permalink to “ADR-0036: Host Applier as a Plugin”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The <code>HostApplier</code> mechanism will be replaced by an applier plugin.</p><ol><li><p><strong>Create <code>handl-plugin-applier</code></strong> (or a similarly named default applier plugin crate).</p><ul><li>Provide <code>DefaultApplierPlugin</code>, a <code>Plugin</code> that reads a host config file and applies it to the host.</li><li>In <code>contribute</code>, read <code>.handl.toml</code> (or another supported config source), parse it into <code>HostConfig</code>, and register the requested kits, plugins, excludes, and option overrides.</li><li>Kits and plugins are loaded by running capabilities (<code>kit/load</code> and <code>load</code>) on the same host, not by calling hard-coded loader/applier code.</li></ul></li><li><p><strong>Turn <code>BasicKitLoader</code> into a <code>KitLoaderPlugin</code></strong> or move its behavior into <code>handl-plugin-applier</code>.</p><ul><li>The default applier provides a <code>kit/load</code> capability.</li><li><code>kit/load</code> accepts a kit name or path and returns a <code>Kit</code> that the applier then registers with the host.</li></ul></li><li><p><strong>The CLI only bootstraps</strong>.</p><ul><li><code>host-cli</code> gains <code>--applier &lt;id&gt;</code> (default <code>applier.default</code>) and <code>--config &lt;path&gt;</code> (default <code>.handl.toml</code>).</li><li>It creates a <code>DefaultHost</code>, registers the default applier plugin (and the default kit/loader plugins if they are not already provided by the applier), tells the applier where the config file is, and calls <code>host.load()</code>.</li><li><code>host.load()</code> runs <code>contribute</code> to a fixed point; the applier reads the config and registers the rest.</li></ul></li><li><p><strong>The existing <code>HostApplier</code> trait and <code>ConfigHostApplier</code> struct can be deprecated</strong>.</p><ul><li><code>HostConfig</code> and <code>KitReference</code>/<code>PluginReference</code> remain in <code>handl-platform</code> as the in-memory model.</li><li>The actual <em>act</em> of applying the config moves from <code>handl-platform</code> to a plugin.</li></ul></li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>With ADR-0035, physical plugin loaders became first-class plugins. The host now loads external plugins through the <code>load</code> capability rather than a hard-coded <code>LoaderRegistry</code>. However, the CLI and <code>DefaultHost</code> still hard-code how a host configuration is applied:</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The CLI no longer imports <code>ConfigHostApplier</code> or <code>BasicKitLoader</code> directly.</li><li><code>.handl.toml</code> becomes the primary input; the CLI becomes a thin launcher.</li><li>A kit can ship its own applier plugin and be selected with <code>--applier</code>.</li><li>Bootstrapping is explicit and minimal: the only hard-coded decisions are which applier to start with and where the config lives.</li><li>The <code>HostConfig</code> parsing code in <code>handl-platform</code> is still reused by the applier plugin.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0036-host-applier-as-plugin.html"><code>design/0036-host-applier-as-plugin.md</code></a>.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};